from __future__ import annotations

import ast
import re
import tokenize
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SRC = ROOT / "src" / "trustheart"

FORBIDDEN_PHRASES = (
    "reproduction of",
    "based on the paper",
    "re-implementation",
    "following the authors",
    "as described by",
    "generated by",
    "ai-assisted",
    "todo from paper",
    "it's worth noting",
    "in conclusion",
    "state-of-the-art",
    "cutting-edge",
)
FORBIDDEN_WORDS = (
    "comprehensive",
    "robust",
    "seamlessly",
    "leveraging",
    "utilize",
    "delve",
    "holistic",
    "meticulously",
    "skeleton",
    "placeholder",
)
EMOJI = re.compile(
    "[\U0001f300-\U0001faff\U00002600-\U000026ff\U00002700-\U000027bf\U00002b00-\U00002bff\U0000fe0f]"
)


def _py_files() -> list[Path]:
    return sorted(SRC.rglob("*.py"))


def test_source_has_no_comments() -> None:
    for path in _py_files():
        with tokenize.open(path) as handle:
            for token in tokenize.generate_tokens(handle.readline):
                assert token.type != tokenize.COMMENT, f"{path}: {token.string}"


def test_source_has_no_docstrings() -> None:
    for path in _py_files():
        tree = ast.parse(path.read_text())
        for node in ast.walk(tree):
            if isinstance(node, ast.Module | ast.FunctionDef | ast.AsyncFunctionDef | ast.ClassDef):
                assert ast.get_docstring(node) is None, path


def test_no_forbidden_phrases() -> None:
    targets = [*_py_files(), ROOT / "README.md", ROOT / "Makefile"]
    for path in targets:
        text = path.read_text().lower()
        for phrase in FORBIDDEN_PHRASES:
            assert phrase not in text, f"{path}: {phrase}"
        for word in FORBIDDEN_WORDS:
            assert re.search(rf"\b{re.escape(word)}\b", text) is None, f"{path}: {word}"


def test_no_emoji() -> None:
    targets = [*_py_files(), ROOT / "README.md"]
    for path in targets:
        assert EMOJI.search(path.read_text()) is None, path
